<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('marketing');$pageTitle='ROI Analysis';$activeMenu='campaign-roi';$rows=db()->query("SELECT campaign_name,campaign_type,budget,actual_spending,generated_sales,status,CASE WHEN actual_spending>0 THEN ((generated_sales-actual_spending)/actual_spending)*100 ELSE 0 END roi FROM campaigns ORDER BY roi DESC")->fetchAll();$totalSpend=array_sum(array_column($rows,'actual_spending'));$totalSales=array_sum(array_column($rows,'generated_sales'));$roi=$totalSpend>0?(($totalSales-$totalSpend)/$totalSpend*100):0;require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Marketing ROI Analysis</h1><p>Return on investment = (Generated Sales − Spending) / Spending × 100.</p></div><button class="btn btn-light border no-print" onclick="window.print()"><i class="fa-solid fa-print me-2"></i>Print / PDF</button></div><div class="row g-3 mb-3"><div class="col-md-4"><div class="kpi-card"><div class="kpi-label">Total Campaign Spend</div><div class="kpi-value"><?=money($totalSpend)?></div></div></div><div class="col-md-4"><div class="kpi-card"><div class="kpi-label">Generated Sales</div><div class="kpi-value"><?=money($totalSales)?></div></div></div><div class="col-md-4"><div class="kpi-card"><div class="kpi-label">Portfolio ROI</div><div class="kpi-value <?=$roi>=0?'roi-positive':'roi-negative'?>"><?=number_format($roi,1)?>%</div></div></div></div><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Campaign</th><th>Type</th><th class="text-end">Budget</th><th class="text-end">Spending</th><th class="text-end">Generated Sales</th><th>ROI</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['campaign_name'])?></td><td><?=e($r['campaign_type'])?></td><td class="text-end"><?=money($r['budget'])?></td><td class="text-end"><?=money($r['actual_spending'])?></td><td class="text-end"><?=money($r['generated_sales'])?></td><td class="<?=$r['roi']>=0?'roi-positive':'roi-negative'?>"><?=number_format((float)$r['roi'],1)?>%</td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
